// Newly designed after the 2026-10-15 recovery. Not the lost migration source.
// Library-only data validation and synchronous fingerprints for atomic IDB work.
import {hash} from '../local-library/protocol/codec.js';
import type {DeviceRecord,Family,InstanceScope} from '../local-library/device-store';
import type {MigrationKind,MigrationScope} from './device-id-transport';
import {publicUuid,uuidPattern} from './validation';
export const DEVICE_ID_SCHEMA=2;
export const MIGRATION_STORES=['records','meta','publicAliases','idMigrationArchives','idMigrationIssues','idMigrationTombstones']as const;
export const MAX_MIGRATION_RECORDS=2_000_000,MAX_MIGRATION_BYTES=256*1024*1024,MAX_MIGRATION_LOOKUPS=100_000;
export type PublicDeviceScope={origin:string;serviceKey:string|null;catalogNamespace:string};
export interface PublicIdOwner{version:2;ownerId:string;scope:PublicDeviceScope;}
export interface AliasEntry{kind:MigrationKind;legacyId:string;id:string;}
export interface LibraryArchive{digest:string;ownerId:string;scope:PublicDeviceScope;record:DeviceRecord;}
export type IssueReason='unresolved'|'not_public'|'wrong_parent'|'collision'|'merged'|'deleted';
export interface MigrationIssue{sourceKey:string;family:Family;key:string;reason:IssueReason;archiveDigest:string;}
export interface MigrationTombstone{family:Family;key:string;updated_at:number;}
export interface MigrationState{scope:InstanceScope;ownerId:string;revision:number;count:number;migrationReason?:string;publicIdOwner?:PublicIdOwner;records:DeviceRecord[];aliases:AliasEntry[];archives:LibraryArchive[];issues:MigrationIssue[];tombstones:MigrationTombstone[];}
export interface PublicDeviceBackup{format:'weebdex-device-library';version:2;id_format:'public_uuid_with_unresolved_legacy';scope:PublicDeviceScope;ownerId:string;revision:number;exported_at:string;records:DeviceRecord[];aliases:AliasEntry[];archives:LibraryArchive[];issues:MigrationIssue[];tombstones:MigrationTombstone[];migration_reason?:string;}
const statuses=['reading','on_hold','plan_to_read','dropped','re_reading','completed'];
const kinds=['manga','chapter','cover','author','group'];
const families=['series','chapters','lists','members'];
const object=(value:unknown):Record<string,unknown>=>{if(!value||typeof value!=='object'||Array.isArray(value)||Object.getPrototypeOf(value)!==null&&Object.getPrototypeOf(Object.getPrototypeOf(value))!==null)throw Error('Expected a library-only plain object');return value as Record<string,unknown>;};
function exact(value:Record<string,unknown>,allowed:readonly string[]){if(Object.keys(value).some(key=>!allowed.includes(key)))throw Error('Unexpected field in library-only data; credentials and identity material are not accepted');}
export function safeInteger(value:unknown):number{if(typeof value!=='number'||!Number.isSafeInteger(value)||value<0)throw Error('Invalid library integer');return value;}
function date(value:unknown):string{if(typeof value!=='string'||value.length>40||!Number.isFinite(Date.parse(value)))throw Error('Invalid library date');return value;}
export function deviceResourceId(value:unknown):string{if(typeof value!=='string')throw Error('Invalid saved resource identifier');if(uuidPattern.test(value))return publicUuid(value);if(!/^[A-Za-z0-9]{10}$/.test(value))throw Error('Invalid saved native resource identifier');return value;}
const listId=(value:unknown):string=>{if(typeof value!=='string'||!/^[0-9a-f]{32}$/.test(value))throw Error('Invalid saved list identifier');return value;};
export const sourceKey=(record:{family:string;key:string})=>JSON.stringify([record.family,record.key]);
export function checkedScope(input:unknown,verified=false):InstanceScope|MigrationScope{const row=object(input);exact(row,['origin','serviceKey','catalogNamespace']);if(typeof row.origin!=='string'||new URL(row.origin).origin!==row.origin||!['http:','https:'].includes(new URL(row.origin).protocol))throw Error('Invalid saved library origin');if(row.serviceKey!==null&&(typeof row.serviceKey!=='string'||!/^[0-9a-f]{64}$/.test(row.serviceKey)))throw Error('Invalid saved service identity');if(row.catalogNamespace!==null&&!( !verified&&typeof row.catalogNamespace==='string'&&/^[0-9a-f]{32}$/.test(row.catalogNamespace)))publicUuid(row.catalogNamespace);if(verified&&(row.serviceKey===null||row.catalogNamespace===null))throw Error('A verified service and catalogue namespace are required');return {origin:row.origin,serviceKey:row.serviceKey as string|null,catalogNamespace:row.catalogNamespace===null?null:!verified&&typeof row.catalogNamespace==='string'&&/^[0-9a-f]{32}$/.test(row.catalogNamespace)?row.catalogNamespace:publicUuid(row.catalogNamespace)};}
export function checkedPublicDeviceScope(input:unknown):PublicDeviceScope{const scope=checkedScope(input);return {...scope,catalogNamespace:publicUuid(scope.catalogNamespace)};}
export const archiveScopeMatches=(archive:PublicDeviceScope,scope:InstanceScope)=>archive.origin===scope.origin&&archive.catalogNamespace===scope.catalogNamespace&&(archive.serviceKey===scope.serviceKey||archive.serviceKey===null);
export function normalizeMigrationRecord(input:unknown):DeviceRecord{
 const value=object(input),family=value.family,updated_at=safeInteger(value.updated_at);if(typeof family!=='string'||!families.includes(family))throw Error('Unsupported saved library family');
 if(family==='series'){exact(value,['family','key','id','status','notification','followedAt','updated_at']);const id=deviceResourceId(value.id);if(value.key!==id||!statuses.includes(String(value.status))||typeof value.notification!=='boolean')throw Error('Invalid saved reading state');return {family,key:id,id,status:String(value.status),notification:value.notification,followedAt:date(value.followedAt),updated_at};}
 if(family==='chapters'){exact(value,['family','key','id','mangaId','completed','page','readAt','updated_at']);const id=deviceResourceId(value.id),mangaId=deviceResourceId(value.mangaId);if(value.key!==id||typeof value.completed!=='boolean')throw Error('Invalid saved chapter state');const page=value.page==null?null:safeInteger(value.page);if(page!==null&&page>0xffffffff)throw Error('Invalid saved page');return {family,key:id,id,mangaId,completed:value.completed,page,...(value.readAt===undefined?{}:{readAt:date(value.readAt)}),updated_at};}
 if(family==='lists'){exact(value,['family','key','id','name','updated_at']);const id=listId(value.id);if(value.key!==id||typeof value.name!=='string'||new TextEncoder().encode(value.name).length>4096)throw Error('Invalid saved list');return {family,key:id,id,name:value.name,updated_at};}
 exact(value,['family','key','list','series','position','updated_at']);const list=listId(value.list),series=deviceResourceId(value.series);if(value.key!==list+':'+series)throw Error('Invalid composite saved list membership');return {family:'members',key:list+':'+series,list,series,position:safeInteger(value.position),updated_at};
}
export function normalizePublicDeviceRecord(input:unknown):DeviceRecord{const row=normalizeMigrationRecord(input);if(row.family==='series')publicUuid(row.id);if(row.family==='chapters'){publicUuid(row.id);publicUuid(row.mangaId);}if(row.family==='members')publicUuid(row.series);return row;}
export function canonicalLibrary(value:unknown):string{
 function clean(value:unknown,depth:number):unknown{if(depth>24)throw Error('Library state nesting limit');if(value===null||typeof value==='boolean'||typeof value==='string')return value;if(typeof value==='number'){if(!Number.isFinite(value))throw Error('Nonfinite library value');return value;}if(Array.isArray(value))return value.map(item=>clean(item,depth+1));const row=object(value);return Object.fromEntries(Object.keys(row).sort().filter(key=>row[key]!==undefined).map(key=>[key,clean(row[key],depth+1)]));}
 const encoded=JSON.stringify(clean(value,0));if(new TextEncoder().encode(encoded).length>MAX_MIGRATION_BYTES)throw Error('Library migration exceeds the 256 MiB state budget');return encoded;
}
export const libraryDigest=(value:unknown)=>hash(new TextEncoder().encode(canonicalLibrary(value)));
export function archiveRecord(record:DeviceRecord,ownerId:string,scope:PublicDeviceScope):LibraryArchive{const content={ownerId:publicUuid(ownerId),scope:checkedPublicDeviceScope(scope),record:normalizeMigrationRecord(record)};return {digest:libraryDigest(content),...content};}
function unique<T>(rows:T[],key:(row:T)=>string,label:string){const seen=new Set<string>();for(const row of rows){const id=key(row);if(seen.has(id))throw Error('Duplicate '+label);seen.add(id);}return rows;}
export function validateMigrationCollections(value:{records:unknown[];aliases:unknown[];archives:unknown[];issues:unknown[];tombstones:unknown[]}){
 for(const name of ['records','aliases','archives','issues','tombstones']as const){const rows=value[name];if(!Array.isArray(rows)||rows.length>MAX_MIGRATION_RECORDS)throw Error('Migration collection exceeds its record budget');}
 const records=unique(value.records.map(normalizeMigrationRecord),sourceKey,'saved record');
 const lists=new Set(records.filter(row=>row.family==='lists').map(row=>row.id));if(records.some(row=>row.family==='members'&&!lists.has(row.list)))throw Error('Saved member references an unknown list');
 const aliases=unique(value.aliases.map(input=>{const row=object(input);exact(row,['kind','legacyId','id']);if(!kinds.includes(String(row.kind))||typeof row.legacyId!=='string'||!(/^[A-Za-z0-9]{10}$/.test(row.legacyId)||uuidPattern.test(row.legacyId)))throw Error('Invalid immutable alias');return {kind:row.kind as MigrationKind,legacyId:deviceResourceId(row.legacyId),id:publicUuid(row.id)};}),row=>row.kind+':'+row.legacyId,'immutable alias');
 const archives=unique(value.archives.map(input=>{const row=object(input);exact(row,['digest','ownerId','scope','record']);const archive=archiveRecord(normalizeMigrationRecord(row.record),publicUuid(row.ownerId),checkedPublicDeviceScope(row.scope));if(row.digest!==archive.digest)throw Error('Library archive digest mismatch');return archive;}),row=>row.digest,'library archive');
 const archiveIds=new Set(archives.map(row=>row.digest)),archiveById=new Map(archives.map(row=>[row.digest,row]));
 const issues=unique(value.issues.map(input=>{const row=object(input);exact(row,['sourceKey','family','key','reason','archiveDigest']);if(!families.includes(String(row.family))||typeof row.key!=='string'||row.sourceKey!==sourceKey({family:String(row.family),key:row.key})||!['unresolved','not_public','wrong_parent','collision','merged','deleted'].includes(String(row.reason))||!archiveIds.has(String(row.archiveDigest)))throw Error('Invalid unresolved library issue');const archived=archiveById.get(String(row.archiveDigest));if(!archived||archived.record.family!==row.family||archived.record.key!==row.key)throw Error('Issue does not describe its archived source row');return {sourceKey:row.sourceKey as string,family:row.family as Family,key:row.key,reason:row.reason as IssueReason,archiveDigest:row.archiveDigest as string};}),row=>row.sourceKey,'migration issue');
 const tombstones=unique(value.tombstones.map(input=>{const row=object(input);exact(row,['family','key','updated_at']);if(!families.includes(String(row.family))||typeof row.key!=='string')throw Error('Invalid deletion fence');if(row.family==='lists')listId(row.key);else if(row.family==='members'){const split=row.key.indexOf(':');if(split!==32)throw Error('Invalid member deletion fence');listId(row.key.slice(0,split));deviceResourceId(row.key.slice(split+1));}else deviceResourceId(row.key);return {family:row.family as Family,key:row.key,updated_at:safeInteger(row.updated_at)};}),sourceKey,'deletion fence');
 const checked={records,aliases,archives,issues,tombstones};canonicalLibrary(checked);return checked;
}
export function validatePublicDeviceBackup(input:unknown):PublicDeviceBackup{const row=object(input);exact(row,['format','version','id_format','scope','ownerId','revision','exported_at','records','aliases','archives','issues','tombstones','migration_reason']);if(row.format!=='weebdex-device-library'||row.version!==2||row.id_format!=='public_uuid_with_unresolved_legacy')throw Error('Unsupported UUID library backup');const scope=checkedPublicDeviceScope(row.scope),ownerId=publicUuid(row.ownerId),collections=validateMigrationCollections({records:row.records as unknown[],aliases:row.aliases as unknown[],archives:row.archives as unknown[],issues:row.issues as unknown[],tombstones:row.tombstones as unknown[]});if(collections.archives.some(archive=>!archiveScopeMatches(archive.scope,scope)))throw Error('Archive belongs to a different catalogue scope');if(row.migration_reason!==undefined&&typeof row.migration_reason!=='string')throw Error('Invalid saved migration fence');const backup:PublicDeviceBackup={format:'weebdex-device-library',version:2,id_format:'public_uuid_with_unresolved_legacy',scope,ownerId,revision:safeInteger(row.revision),exported_at:date(row.exported_at),...collections,...(row.migration_reason?{migration_reason:row.migration_reason as string}:{})};canonicalLibrary(backup);return backup;}
export function publicDeviceBackup(state:MigrationState,exported_at=new Date().toISOString()):PublicDeviceBackup{if(!state.publicIdOwner)throw Error('This device library has not been explicitly migrated');return validatePublicDeviceBackup({format:'weebdex-device-library',version:2,id_format:'public_uuid_with_unresolved_legacy',scope:state.scope,ownerId:state.ownerId,revision:state.revision,exported_at,records:state.records,aliases:state.aliases,archives:state.archives,issues:state.issues,tombstones:state.tombstones,...(state.migrationReason?{migration_reason:state.migrationReason}:{})});}
export function freezeLibrary<T>(value:T):Readonly<T>{if(value&&typeof value==='object'){for(const entry of Object.values(value))freezeLibrary(entry);Object.freeze(value);}return value;}
